Standard flood fill with an explicit stack (avoids recursion limits on large grids):

```python
from collections import deque


def count_islands(grid) -> int:
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if grid[0] is not None else 0
    if cols == 0:
        return 0

    seen = [[False] * cols for _ in range(rows)]
    count = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '#' or seen[r][c]:
                continue
            count += 1
            seen[r][c] = True
            stack = deque([(r, c)])
            while stack:
                y, x = stack.pop()
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < rows and 0 <= nx < cols:
                        if not seen[ny][nx] and grid[ny][nx] == '#':
                            seen[ny][nx] = True
                            stack.append((ny, nx))
    return count
```

Each land cell is visited once, so the runtime is O(rows × cols).
